from pathlib import Path

p=Path('FactionLedgerIQ.user.js')
s=p.read_text()
s=s.replace('// @version      1.0.6','// @version      1.0.7',1)
s=s.replace("const VERSION='1.0.6';","const VERSION='1.0.7';",1)

old="""async function importReceipt(text){const p=extractPayload(text);if(p.kind==='PAYMENT'){let n=0;p.claims.forEach(x=>{const c=claimById(x.id);if(!c||c.status==='VOID')return;c.status='REIMBURSED';c.reimbursedAt=p.paidAt||p.generatedAt||new Date().toISOString();c.reimbursementBatchId=p.batchId;n++;});save();toast(n+' claim(s) marked reimbursed');return;}if(p.kind!=='MOVEMENT')throw new Error('Unsupported LedgerIQ receipt');const verification=await verifyMovementPayload(p),statuses=p.claims.map(c=>{const old=state.auditClaims.find(a=>a.claimId===c.id),m=p.movements.find(x=>x.movementId===c.movementId),v=m?verification[m.movementId]:'UNVERIFIED';let status='NEW';if(old&&old.status==='PAID')status='ALREADY_PAID';else if(old&&Number(old.amount||0)!==Number(c.amount||0))status='REVIEW';else if(v==='UNVERIFIED'||v==='MEMBER_VERIFIED')status='REVIEW';return{claim:c,existing:old,status,verification:v};});currentAudit={payload:p,verification,claimStatuses:statuses};activeTab='audit';render();}
function payAudit(){if(!currentAudit)return;const p=currentAudit.payload,payable=currentAudit.claimStatuses.filter(r=>r.status==='NEW');if(!payable.length){toast('No new verified claims to pay');return;}const paidAt=new Date().toISOString();payable.forEach(r=>{let a=state.auditClaims.find(x=>x.claimId===r.claim.id);if(!a){a={id:uid('AUD'),claimId:r.claim.id,sourceBatchId:p.batchId,playerName:p.player&&p.player.name||'',playerId:p.player&&p.player.id||'',itemId:r.claim.itemId,itemName:r.claim.itemName,qty:r.claim.qty,amount:r.claim.amount,status:'PAID',paidAt,importedAt:new Date().toISOString()};state.auditClaims.push(a);}else{a.status='PAID';a.paidAt=paidAt;}});const pay={kind:'PAYMENT',version:VERSION,batchId:uid('PAY'),generatedAt:new Date().toISOString(),paidAt,member:{name:p.player&&p.player.name||'',id:p.player&&p.player.id||''},leadership:{name:state.settings.playerName||'',id:state.settings.playerId||''},claims:payable.map(r=>({id:r.claim.id,itemId:r.claim.itemId,itemName:r.claim.itemName,qty:r.claim.qty,amount:r.claim.amount}))};pay.total=pay.claims.reduce((n,c)=>n+Number(c.amount||0),0);state.paymentBatches.push({id:pay.batchId,sourceBatchId:p.batchId,paidAt,claimIds:pay.claims.map(c=>c.id),total:pay.total});currentAudit=null;save(false);showReceipt('Discord Reimbursement Receipt',paymentReceipt(pay));render();}
"""
new="""async function importReceipt(text){const p=extractPayload(text);if(p.kind==='PAYMENT'){let n=0;p.claims.forEach(x=>{const c=claimById(x.id);if(!c||c.status==='VOID')return;c.status='REIMBURSED';c.reimbursedAt=p.paidAt||p.generatedAt||new Date().toISOString();c.reimbursementBatchId=p.batchId;n++;});save();toast(n+' claim(s) marked reimbursed');return;}if(p.kind!=='MOVEMENT')throw new Error('Unsupported LedgerIQ receipt');const verification=await verifyMovementPayload(p),statuses=p.claims.map(c=>{const old=state.auditClaims.find(a=>a.claimId===c.id),m=p.movements.find(x=>x.movementId===c.movementId),v=m?verification[m.movementId]:'UNVERIFIED';let status='NEW',reviewReason='',manualEligible=false;if(old&&old.status==='PAID'){status='ALREADY_PAID';reviewReason='Claim ID is already recorded as paid';}else if(old&&Number(old.amount||0)!==Number(c.amount||0)){status='REVIEW';reviewReason='Claim amount conflicts with existing audit history';}else if(v==='UNVERIFIED'||v==='MEMBER_VERIFIED'){status='REVIEW';reviewReason=v==='MEMBER_VERIFIED'?'Member API verified; leadership API could not independently confirm':'Leadership API could not independently confirm';manualEligible=true;}return{claim:c,existing:old,status,verification:v,reviewReason,manualEligible};});currentAudit={payload:p,verification,claimStatuses:statuses};activeTab='audit';render();}
function payAudit(mode='verified'){if(!currentAudit)return;const p=currentAudit.payload,manual=mode==='manual',payable=currentAudit.claimStatuses.filter(r=>manual?(r.status==='REVIEW'&&r.manualEligible):r.status==='NEW');if(!payable.length){toast(manual?'No manually approvable REVIEW claims':'No new verified claims to pay');return;}const paidAt=new Date().toISOString(),verificationMethod=manual?'MANUAL_LEADERSHIP':'API_VERIFIED';payable.forEach(r=>{let a=state.auditClaims.find(x=>x.claimId===r.claim.id);if(!a){a={id:uid('AUD'),claimId:r.claim.id,sourceBatchId:p.batchId,playerName:p.player&&p.player.name||'',playerId:p.player&&p.player.id||'',itemId:r.claim.itemId,itemName:r.claim.itemName,qty:r.claim.qty,amount:r.claim.amount,status:'PAID',paidAt,importedAt:new Date().toISOString(),verificationMethod,verificationDetail:r.verification||''};state.auditClaims.push(a);}else{a.status='PAID';a.paidAt=paidAt;a.verificationMethod=verificationMethod;a.verificationDetail=r.verification||'';}});const pay={kind:'PAYMENT',version:VERSION,batchId:uid('PAY'),generatedAt:new Date().toISOString(),paidAt,member:{name:p.player&&p.player.name||'',id:p.player&&p.player.id||''},leadership:{name:state.settings.playerName||'',id:state.settings.playerId||''},verificationMethod,claims:payable.map(r=>({id:r.claim.id,itemId:r.claim.itemId,itemName:r.claim.itemName,qty:r.claim.qty,amount:r.claim.amount,verificationMethod,verificationDetail:r.verification||''}))};pay.total=pay.claims.reduce((n,c)=>n+Number(c.amount||0),0);state.paymentBatches.push({id:pay.batchId,sourceBatchId:p.batchId,paidAt,claimIds:pay.claims.map(c=>c.id),total:pay.total,verificationMethod});currentAudit=null;save(false);showReceipt('Discord Reimbursement Receipt',paymentReceipt(pay));render();}
"""
if old not in s:
    raise SystemExit('audit logic block not found')
s=s.replace(old,new,1)

old="""function paymentReceipt(p){const l=['**FACTION LEDGER IQ — REIMBURSEMENT**','',`Paid To: ${p.member.name||'Unknown'}${p.member.id?' ['+p.member.id+']':''}`,`Recorded By: ${p.leadership.name||'Leadership'}${p.leadership.id?' ['+p.leadership.id+']':''}`,`Payment Batch: \\`${p.batchId}\\``,''];p.claims.forEach(c=>l.push(`**${c.itemName}**`,`Qty: ${Number(c.qty||0).toLocaleString()}`,'Paid: **'+money(c.amount)+'**',`Claim ID: \\`${c.id}\\``,' '));l.push('**TOTAL REIMBURSED:** '+money(p.total),'','FLIQ-AUDIT:'+encodePayload(p));return l.join('\\n');}
"""
new="""function paymentReceipt(p){const method=p.verificationMethod==='MANUAL_LEADERSHIP'?'Manual leadership approval':'Independent API verification',l=['**FACTION LEDGER IQ — REIMBURSEMENT**','',`Paid To: ${p.member.name||'Unknown'}${p.member.id?' ['+p.member.id+']':''}`,`Recorded By: ${p.leadership.name||'Leadership'}${p.leadership.id?' ['+p.leadership.id+']':''}`,`Verification: ${method}`,`Payment Batch: \\`${p.batchId}\\``,''];p.claims.forEach(c=>l.push(`**${c.itemName}**`,`Qty: ${Number(c.qty||0).toLocaleString()}`,'Paid: **'+money(c.amount)+'**',`Claim ID: \\`${c.id}\\``,' '));l.push('**TOTAL REIMBURSED:** '+money(p.total),'','FLIQ-AUDIT:'+encodePayload(p));return l.join('\\n');}
"""
if old not in s:
    raise SystemExit('paymentReceipt block not found')
s=s.replace(old,new,1)

start=s.find('function auditHtml(){')
end=s.find('function settingsHtml(){',start)
if start<0 or end<0:
    raise SystemExit('auditHtml boundaries not found')
new_audit="""function auditHtml(){let result='';if(currentAudit){const p=currentAudit.payload,total=p.claims.reduce((n,c)=>n+Number(c.amount||0),0),hasNew=currentAudit.claimStatuses.some(r=>r.status==='NEW'),hasManual=currentAudit.claimStatuses.some(r=>r.status==='REVIEW'&&r.manualEligible);result=`<div class=\"fliq-section\"><div class=\"fliq-section-title\"><span>Audit Result</span><span>${money(total)}</span></div><div><b>${esc(p.player&&p.player.name||'Unknown')}</b>${p.player&&p.player.id?' ['+esc(p.player.id)+']':''} · ${esc(p.batchId)}</div><div class=\"fliq-list\" style=\"margin-top:8px\">${currentAudit.claimStatuses.map(r=>`<div class=\"fliq-list-item\"><div class=\"fliq-item-top\"><div><b>${esc(r.claim.itemName)}</b> ×${Number(r.claim.qty||0).toLocaleString()} · ${money(r.claim.amount)}<div class=\"fliq-muted\">${esc(r.claim.id)} · ${esc(r.verification)}</div>${r.reviewReason?`<div class=\"fliq-muted\">${esc(r.reviewReason)}</div>`:''}</div><span class=\"fliq-pill ${r.status==='NEW'?'green':r.status==='ALREADY_PAID'?'red':'gold'}\">${esc(r.status)}</span></div></div>`).join('')}</div><div class=\"fliq-actions\">${hasNew?'<button class=\"fliq-btn fliq-btn-primary\" data-fliq=\"audit-pay\">Mark NEW Claims Paid + Create Receipt</button>':''}${hasManual?'<button class=\"fliq-btn\" data-fliq=\"audit-manual-pay\">Approve REVIEW & Pay</button>':''}<button class=\"fliq-btn\" data-fliq=\"audit-clear\">Clear</button></div>${hasManual?'<div class=\"fliq-muted\" style=\"margin-top:7px\">Use manual approval only after leadership independently checks the movement in Torn. The reimbursement receipt will record manual leadership approval.</div>':''}</div>`;}const paid=state.auditClaims.filter(a=>a.status==='PAID').slice().sort((a,b)=>new Date(b.paidAt)-new Date(a.paidAt)).slice(0,25);return `<div class=\"fliq-section\"><div class=\"fliq-section-title\"><span>Leadership Audit Import</span></div><div class=\"fliq-muted\">Paste the member Discord movement receipt. Claim IDs are checked against paid history and Armory movement is checked against faction news when your key has access.</div><textarea id=\"fliq-audit-import\" class=\"fliq-textarea\" placeholder=\"Paste member movement receipt\"></textarea><div class=\"fliq-actions\"><button class=\"fliq-btn fliq-btn-primary\" data-fliq=\"audit-import\">Audit Receipt</button></div></div>${result}<div class=\"fliq-section\"><div class=\"fliq-section-title\"><span>Paid Claim History</span><span class=\"fliq-muted\">${state.auditClaims.filter(a=>a.status==='PAID').length}</span></div><div class=\"fliq-list\">${paid.map(a=>`<div class=\"fliq-list-item\"><b>${esc(a.playerName||a.playerId)}</b> · ${esc(a.itemName)} ×${Number(a.qty||0).toLocaleString()} · ${money(a.amount)}<div class=\"fliq-muted\">${esc(a.claimId)} · ${esc(fmt(a.paidAt))}${a.verificationMethod?' · '+esc(a.verificationMethod==='MANUAL_LEADERSHIP'?'Manual approval':'API verified'):''}</div></div>`).join('')||'<div class=\"fliq-muted\">No leadership reimbursements recorded yet.</div>'}</div></div>`;}\n"""
s=s[:start]+new_audit+s[end:]

old="if(a==='audit-pay'){payAudit();return;}if(a==='audit-clear')"
new="if(a==='audit-pay'){payAudit('verified');return;}if(a==='audit-manual-pay'){payAudit('manual');return;}if(a==='audit-clear')"
if old not in s:
    raise SystemExit('action audit-pay block not found')
s=s.replace(old,new,1)

p.write_text(s)
